            ps1.executeUpdate();

            PreparedStatement ps2 = con2.prepareStatement("UPDATE accounts SET balance = balance + 100 WHERE id=2");
            ps2.executeUpdate();

            con1.commit();
            con2.commit();

            System.out.println("Distributed Transaction Committed");

        } catch (Exception e) {
            try {
                if (con1 != null) con1.rollback();
                if (con2 != null) con2.rollback();
            } catch (Exception ex) {}

            System.out.println("Distributed Transaction Rolled Back");
        }
    }
}

